/* ============================================
   ACCORDION COMPONENT
   Collapsible content sections
   ============================================ */

/* The standard card surface (container fill, hairline border,
   --radius-300), the one SelectionCard's and QuestionCard's option rows
   share, so a collapsible section reads as a card on the page rather than
   a hairline floating over it. */
.ds-accordion {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-300);
  background-color: var(--color-bg-container-primary);
  overflow: hidden;
}

/* ============================================
   ITEM
   ============================================ */

.ds-accordion__item {
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
}

.ds-accordion__item:last-child {
  border-bottom: none;
}

/* ============================================
   TRIGGER
   ============================================ */

.ds-accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: var(--gap-200);
  padding: var(--padding-400) var(--padding-500);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

/* Hover steps the header to the secondary fill, the collapsible-section
   convention the agent cards (AgentPlan, SourceTrail, ToolCall) set. */
.ds-accordion__trigger:hover {
  background-color: var(--color-bg-container-secondary);
}

.ds-accordion__trigger:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
  border-radius: var(--radius-300);
}

/* ============================================
   TITLE
   ============================================ */

.ds-accordion__title {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

/* ============================================
   ICON
   ============================================ */

.ds-accordion__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-500);
  color: var(--color-icon-primary);
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-accordion__item--open .ds-accordion__icon {
  transform: rotate(180deg);
}

/* ============================================
   PANEL
   ============================================ */

.ds-accordion__panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-accordion__item--open .ds-accordion__panel {
  grid-template-rows: 1fr;
}

/* ============================================
   CONTENT
   ============================================ */

.ds-accordion__content {
  overflow: hidden;
  padding: 0 var(--padding-500);
  transition: padding var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-accordion__item--open .ds-accordion__content {
  padding: 0 var(--padding-500) var(--padding-400);
}

.ds-accordion__content p {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
  margin: 0;
}

'use client';

import React, { useState, useId } from 'react';
import './Accordion.css';
import '../../fonts/material-symbols.css';

export interface AccordionItem {
  /** Unique identifier */
  id: string;
  /** Header text */
  title: string;
  /** Body content */
  content: React.ReactNode;
}

/** Props owned by Accordion itself — everything else falls through to the wrapper. */
type AccordionOwnProps = {
  /** List of accordion items */
  items: AccordionItem[];
  /** Allow multiple items open at once */
  multiple?: boolean;
  /**
   * IDs of the expanded items, for a controlled accordion. Leave it undefined
   * to let the component keep its own open state, seeded from
   * `defaultExpanded`.
   */
  expanded?: string[];
  /** IDs of initially expanded items when the accordion is uncontrolled */
  defaultExpanded?: string[];
  /** Called with the IDs of the expanded items after the user opens or closes one */
  onExpandedChange?: (expanded: string[]) => void;
  /** Additional CSS classes */
  className?: string;
};

export interface AccordionProps
  extends AccordionOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof AccordionOwnProps | 'children'> {}

/**
 * Accordion organises content into collapsible sections.
 * Supports single or multiple open panels.
 *
 * Forwards a ref to the wrapping element and spreads unrecognised props onto
 * it.
 */
export const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  (
    {
      items,
      multiple = false,
      expanded,
      defaultExpanded = [],
      onExpandedChange,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const isControlled = expanded !== undefined;
    const [internalExpanded, setInternalExpanded] = useState<string[]>(defaultExpanded);
    const openIds = isControlled ? expanded : internalExpanded;
    // Header and panel ids are scoped to this instance, so two accordions
    // whose items share ids never point at each other's panels.
    const instanceId = useId();
    const baseClass = 'ds-accordion';
    const classes = [baseClass, className].filter(Boolean).join(' ');

    const toggle = (id: string) => {
      const next = openIds.includes(id)
        ? openIds.filter((openId) => openId !== id)
        : multiple
          ? [...openIds, id]
          : [id];
      if (!isControlled) setInternalExpanded(next);
      onExpandedChange?.(next);
    };

    return (
      <div {...rest} ref={ref} className={classes}>
        {items.map((item) => {
          const isOpen = openIds.includes(item.id);
          const headerId = `${instanceId}-header-${item.id}`;
          const panelId = `${instanceId}-panel-${item.id}`;
          return (
            <div
              key={item.id}
              className={`${baseClass}__item${isOpen ? ` ${baseClass}__item--open` : ''}`}
            >
              <button
                type="button"
                className={`${baseClass}__trigger`}
                aria-expanded={isOpen}
                aria-controls={panelId}
                id={headerId}
                onClick={() => toggle(item.id)}
              >
                <span className={`${baseClass}__title`}>{item.title}</span>
                <span
                  className={`${baseClass}__icon material-symbols-rounded`}
                  aria-hidden="true"
                >
                  expand_more
                </span>
              </button>
              {/* A closed panel is still laid out (its rows collapse to zero for
                  the transition), so `inert` takes its content out of the tab
                  order and the accessibility tree until it opens. */}
              <div
                id={panelId}
                aria-labelledby={headerId}
                className={`${baseClass}__panel`}
                inert={!isOpen}
              >
                <div className={`${baseClass}__content`}>{item.content}</div>
              </div>
            </div>
          );
        })}
      </div>
    );
  },
);

Accordion.displayName = 'Accordion';
